A Hamiltonian path visits every vertex exactly once. Deciding whether one exists is NP-complete, so no polynomial-time algorithm is known. The classic exact method is bitmask dynamic programming in O(2^n * n^2) time, fine for around 20 vertices.

```python
def has_ham_path(n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    dp = [[False] * n for _ in range(1 << n)]  # dp[visited][last]
    for v in range(n):
        dp[1 << v][v] = True
    for mask in range(1 << n):
        for v in range(n):
            if dp[mask][v]:
                for w in adj[v]:
                    if not mask >> w & 1:
                        dp[mask | 1 << w][w] = True
    return any(dp[(1 << n) - 1])


print(has_ham_path(3, [(0, 1), (1, 2)]))          # True
print(has_ham_path(4, [(0, 1), (0, 2), (0, 3)]))  # False
```

In a directed acyclic graph, process vertices in topological order and relax each outgoing edge once. That gives shortest paths in O(V + E), faster than Dijkstra, and it works even with negative edge weights.

```python
from graphlib import TopologicalSorter


def dag_shortest(graph, src):
    # graph: {u: [(v, w), ...]}
    preds = {u: set() for u in graph}
    for u, edges in graph.items():
        for v, _ in edges:
            preds.setdefault(v, set()).add(u)
    dist = {u: float("inf") for u in preds}
    dist[src] = 0
    for u in TopologicalSorter(preds).static_order():
        for v, w in graph.get(u, []):
            dist[v] = min(dist[v], dist[u] + w)
    return dist


g = {"a": [("b", 2), ("c", 5)], "b": [("c", -1)], "c": []}
print(dag_shortest(g, "a"))  # {'a': 0, 'b': 2, 'c': 1}
```

