A decorator that takes arguments is a factory: the outer function takes the arguments, returns the real decorator, and that returns the wrapper. That makes three nested functions.

```python
import functools


def repeat(times):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for _ in range(times):
                result = func(*args, **kwargs)
            return result
        return wrapper
    return decorator


@repeat(3)
def hello():
    print("hi")


hello()  # prints hi three times
```

`@repeat(3)` first calls `repeat(3)`, then applies the result to `hello`. Forgetting the parentheses is a common bug.

To reverse a linked list in groups of k, count k nodes, reverse that segment in place, and link it to the result of recursing on the rest. If fewer than k nodes remain, leave them as they are.

```python
class Node:
    def __init__(self, val, next=None):
        self.val, self.next = val, next


def reverse_k(head, k):
    node, n = head, 0
    while node and n < k:
        node, n = node.next, n + 1
    if n < k:
        return head
    prev, cur = reverse_k(node, k), head
    for _ in range(k):
        cur.next, prev, cur = prev, cur, cur.next
    return prev


head = Node(1, Node(2, Node(3, Node(4, Node(5)))))
node = reverse_k(head, 2)
out = []
while node:
    out.append(node.val)
    node = node.next
print(out)  # [2, 1, 4, 3, 5]
```

